        "fs", "fx", "fr", "fi", "oi", "od",
        "fb", "fp", "fq",
        "br",
        "hm", "fm", "fh",
        "fa", "fe", "ah",
        "ts", "tk", "tg", "tx",
        "ep", "fw",
